-- Operación, modificaciones y simulación del presupuesto de nómina.
create table if not exists public.hr_payroll_budget_modifications(
 id uuid primary key default gen_random_uuid(),budget_line_id uuid not null references public.hr_payroll_budget_lines(id),budget_year integer not null,
 modification_type text not null check(modification_type in('AUMENTO','REDUCCION')),amount numeric(18,2) not null check(amount>0),reason text not null,
 previous_monthly_amount numeric(18,2) not null,new_monthly_amount numeric(18,2) not null,effective_month integer not null check(effective_month between 1 and 12),
 created_by uuid not null references public.app_users(id),created_at timestamptz not null default now()
);
create index if not exists hr_payroll_budget_modifications_year_idx on public.hr_payroll_budget_modifications(budget_year,created_at desc);
alter table public.hr_payroll_budget_modifications enable row level security;
revoke all on public.hr_payroll_budget_modifications from anon,authenticated;

create or replace function public.list_hr_payroll_budget_operations(p_token text,p_year integer,p_month integer)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare v_user public.app_users;v_elapsed integer:=greatest(1,least(p_month,12));begin v_user:=public.hr_authenticated_user(p_token);
 if v_user.id is null or (v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'ver_recursos_humanos')::boolean,false)) then return jsonb_build_object('success',false,'error','No posee permiso para consultar la operación presupuestaria de nómina.');end if;
 return jsonb_build_object('success',true,'year',p_year,'month',p_month,
 'summary',(with budget as(select coalesce(sum(monthly_amount),0) monthly,coalesce(sum(monthly_amount)*12,0) annual from public.hr_payroll_budget_lines where budget_year=p_year and active),executed as(select coalesce(sum(l.gross_salary),0) ytd,coalesce(sum(l.gross_salary) filter(where b.payroll_month=p_month),0) current_month,count(distinct b.payroll_month) months from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=p_year) select jsonb_build_object('monthly_budget',budget.monthly,'annual_budget',budget.annual,'executed_month',executed.current_month,'executed_ytd',executed.ytd,'available_month',budget.monthly-executed.current_month,'available_annual',budget.annual-executed.ytd,'projected_year',executed.ytd+(executed.ytd/greatest(executed.months,1))*(12-v_elapsed),'overdraft',executed.current_month>budget.monthly) from budget cross join executed),
 'execution',coalesce((with programmed as(select execution_fund,program,subproduct,activity,sum(monthly_amount) programmed from public.hr_payroll_budget_lines where budget_year=p_year and active group by execution_fund,program,subproduct,activity),executed as(select l.execution_fund,l.program,l.subproduct,l.activity,sum(l.gross_salary) executed from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=p_year and b.payroll_month=p_month group by l.execution_fund,l.program,l.subproduct,l.activity),x as(select coalesce(p.execution_fund,e.execution_fund) execution_fund,coalesce(p.program,e.program) program,coalesce(p.subproduct,e.subproduct) subproduct,coalesce(p.activity,e.activity) activity,coalesce(p.programmed,0) programmed,coalesce(e.executed,0) executed,coalesce(p.programmed,0)-coalesce(e.executed,0) available,coalesce(e.executed,0)>coalesce(p.programmed,0) overdraft from programmed p full join executed e using(execution_fund,program,subproduct,activity)) select jsonb_agg(to_jsonb(x) order by execution_fund,program,subproduct,activity) from x),'[]'::jsonb),
 'monthly_execution',coalesce((select jsonb_agg(to_jsonb(x) order by x.payroll_month) from(select b.payroll_month,sum(l.gross_salary) executed,(select coalesce(sum(monthly_amount),0) from public.hr_payroll_budget_lines where budget_year=p_year and active) programmed from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=p_year group by b.payroll_month)x),'[]'::jsonb),
 'modifications',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'budget_line_id',m.budget_line_id,'payroll_type',l.payroll_type,'classification',concat('Fondo ',l.execution_fund,' · ',l.program,'/',l.subproduct,'/',l.activity),'modification_type',m.modification_type,'amount',m.amount,'reason',m.reason,'previous_monthly_amount',m.previous_monthly_amount,'new_monthly_amount',m.new_monthly_amount,'effective_month',m.effective_month,'created_at',m.created_at,'user_name',u.full_name) order by m.created_at desc) from public.hr_payroll_budget_modifications m join public.hr_payroll_budget_lines l on l.id=m.budget_line_id join public.app_users u on u.id=m.created_by where m.budget_year=p_year),'[]'::jsonb));end $$;

create or replace function public.save_hr_payroll_budget_modification(p_token text,p_line_id uuid,p_type text,p_amount numeric,p_reason text,p_effective_month integer)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare v_user public.app_users;v_line public.hr_payroll_budget_lines;v_new numeric;begin v_user:=public.hr_authenticated_user(p_token);select * into v_line from public.hr_payroll_budget_lines where id=p_line_id for update;
 if v_user.id is null or v_line.id is null or (v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'editar_recursos_humanos')::boolean,false)) then return jsonb_build_object('success',false,'error','No posee permiso para modificar el presupuesto de nómina.');end if;
 if p_type not in('AUMENTO','REDUCCION') or p_amount<=0 or trim(coalesce(p_reason,''))='' or p_effective_month not between 1 and 12 then return jsonb_build_object('success',false,'error','Complete correctamente el tipo, monto, mes efectivo y motivo.');end if;
 v_new:=v_line.monthly_amount+case when p_type='AUMENTO' then p_amount else -p_amount end;if v_new<0 then return jsonb_build_object('success',false,'error','La reducción supera el presupuesto mensual de la partida.');end if;
 insert into public.hr_payroll_budget_modifications(budget_line_id,budget_year,modification_type,amount,reason,previous_monthly_amount,new_monthly_amount,effective_month,created_by) values(v_line.id,v_line.budget_year,p_type,p_amount,trim(p_reason),v_line.monthly_amount,v_new,p_effective_month,v_user.id);
 update public.hr_payroll_budget_lines set monthly_amount=v_new,updated_at=now() where id=v_line.id;insert into public.security_audit_log(actor_user_id,action,module,detail) values(v_user.id,'MODIFICAR_PRESUPUESTO_NOMINA','Recursos Humanos',jsonb_build_object('line_id',v_line.id,'type',p_type,'amount',p_amount,'reason',p_reason,'previous',v_line.monthly_amount,'new',v_new,'effective_month',p_effective_month));return jsonb_build_object('success',true,'new_monthly_amount',v_new);end $$;

create or replace function public.simulate_hr_payroll_budget(p_token text,p_year integer,p_month integer,p_salary_increase numeric,p_new_hires integer,p_new_hire_salary numeric)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare v_user public.app_users;v_annual numeric;v_executed numeric;v_remaining integer:=greatest(0,13-p_month);v_impact numeric;begin v_user:=public.hr_authenticated_user(p_token);
 if v_user.id is null or (v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'ver_recursos_humanos')::boolean,false)) then return jsonb_build_object('success',false,'error','No posee permiso para simular el presupuesto.');end if;
 select coalesce(sum(monthly_amount)*12,0) into v_annual from public.hr_payroll_budget_lines where budget_year=p_year and active;select coalesce(sum(l.gross_salary),0) into v_executed from public.hr_payroll_batch_lines l join public.hr_payroll_batches b on b.id=l.batch_id where b.payroll_year=p_year;v_impact:=(greatest(p_salary_increase,0)+greatest(p_new_hires,0)*greatest(p_new_hire_salary,0))*v_remaining;
 return jsonb_build_object('success',true,'remaining_months',v_remaining,'current_annual_budget',v_annual,'executed_ytd',v_executed,'simulated_impact',v_impact,'projected_commitment',v_executed+v_impact,'projected_available',v_annual-v_executed-v_impact,'overdraft',v_executed+v_impact>v_annual);end $$;
grant execute on function public.list_hr_payroll_budget_operations(text,integer,integer),public.save_hr_payroll_budget_modification(text,uuid,text,numeric,text,integer),public.simulate_hr_payroll_budget(text,integer,integer,numeric,integer,numeric) to anon,authenticated;
